bool guard(const V& op,const V& payload,const O& saved,const O& policies){need(op.isObject()&&op.object().size()==3&&f(op,"kind")==V("b_source_map_controls"),"SOURCE_MAP_CLOSED_OPERATOR");const auto key=f(op,"source_key").string();const auto i=rows.find(key);need(i!=rows.end(),"SOURCE_MAP_EXACT_KEY");const auto stage=f(op,"stage").string();const auto& pg=i->second.program;const auto& node=f(f(f(pg,"graph"),"nodes"),stage);if(!includes(payload,f(node,"expected")))return false;if(stage=="source_choices")return known(payload);const bool repair=stage=="restore_two_source_descent_forms";const auto* ch=choices(saved,policies,key,repair);if(!ch||f(payload,"reported_chosen_muting_method")!=f(*ch,"chosen_muting_method"))return false;auto top=payload;top.object().erase("actual_ordered_notes");if(!known(top))return false;const auto* p=phase(i->second,stage);if(p&&p->find("reports"))if(f(payload,"actual_ordered_notes")!=expectedReports(key,stage,*ch))return false;if(const auto* reported=payload.find("reported_actual_chosen_descent_convention"))if(*reported!=f(*ch,"chosen_descent_convention"))return false;if(const auto* reported=payload.find("reported_actual_chosen_second_pass_subdivision"))if(*reported!=f(*ch,"chosen_second_pass_subdivision"))return false;if(repair){const auto* retainedPolicy=retained(policies,key);if(!retainedPolicy||!truth(*retainedPolicy,"known_directional_debt"))return false;}return stage!="actual_source_audit"||policyComplete(key,policies);}
