void policyBefore(const std::string& key,const std::string& stage,const V& payload,O& all){const auto i=rows.find(key);if(i==rows.end()||!payload.isObject()||!truth(f(i->second.program,"source_rules"),"known_directional_repair")||stage=="restore_two_source_descent_forms")return;const auto* p=phase(i->second,stage);if(!p||!p->find("reports"))return;auto& retainedPolicy=policy(all,key);bool wrong=truth(payload,"F_Fsharp_G_Gsharp_changed_without_intention_reported");const auto* actual=payload.find("actual_ordered_notes");if(actual&&actual->isArray()&&known(*actual)&&!f(retainedPolicy,"choices").null()){const auto expected=expectedReports(key,stage,f(retainedPolicy,"choices"));if(actual->array().size()==expected.array().size())for(std::size_t j=0;j<actual->array().size();++j){const auto& a=f(actual->array()[j],"reported_actual_note_name"),e=f(expected.array()[j],"reported_actual_note_name");if((e==V("F")&&a==V("F#"))||(e==V("F#")&&a==V("F"))||(e==V("G")&&a==V("G#"))||(e==V("G#")&&a==V("G")))wrong=true;}}if(wrong)retainedPolicy.object()["known_directional_debt"]=true;}
